@isTest private class CoreStdlibSupportedCloseoutTest {
  private class DTO { public String Name; public Integer Count; public Decimal Amount; public List<String> Tags; }

  @isTest static void rows() {
    Decimal roundPositive = Decimal.valueOf('12.5');
    System.assertEquals(12, roundPositive.round());
    Decimal roundNegative = Decimal.valueOf('-1.5');
    System.assertEquals(-2, roundNegative.round());
    System.assertEquals(12.34, Decimal.valueOf('12.345').setScale(2));
    System.assertEquals(1.3, Decimal.valueOf('1.25').setScale(1, RoundingMode.HALF_UP));

    String encoded = EncodingUtil.urlEncode('a b+c/%', 'UTF-8');
    System.assertEquals('a+b%2Bc%2F%25', encoded);
    System.assertEquals('a b+c/%', EncodingUtil.urlDecode(encoded, 'UTF-8'));
    String digestHex = EncodingUtil.convertToHex(Crypto.generateDigest('SHA-256', Blob.valueOf('abc')));
    System.assertEquals('ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad', digestHex);

    List<String> split = 'alpha,beta,,gamma,'.split(',', -1);
    System.assertEquals(5, split.size());
    System.assertEquals('', split.get(2));
    System.assertEquals('', split.get(4));
    List<String> limited = 'one:two:three'.split(':', 2);
    System.assertEquals(2, limited.size());
    System.assertEquals('two:three', limited.get(1));

    Pattern p = Pattern.compile('([A-Z]+)([0-9]+)?');
    Matcher m = p.matcher('abc DEF42 ghi XYZ');
    System.assert(m.find());
    System.assertEquals('DEF42', m.group());
    System.assertEquals('DEF', m.group(1));
    System.assertEquals('42', m.group(2));
    System.assert(m.find());
    System.assertEquals('XYZ', m.group());
    System.assertEquals(null, m.group(2));
    System.assert(Pattern.matches('[0-9]+', '12345'));
    System.assert(Pattern.compile('[a-z]+').matcher('trail').matches());

    DTO dto = new DTO();
    dto.Name = 'Cabin';
    dto.Count = 3;
    dto.Amount = 12.34;
    dto.Tags = new List<String>{'spruce', 'lake'};
    String compact = JSON.serialize(dto);
    System.assert(compact.contains('"Name":"Cabin"'));
    System.assert(compact.contains('"Count":3'));
    System.assert(compact.contains('"Amount":12.34'));
    System.assert(compact.contains('"Tags":["spruce","lake"]'));
    String pretty = JSON.serializePretty(dto);
    System.assert(pretty.contains('"Name" : "Cabin"'));
    System.assert(pretty.contains('"Count" : 3'));
    System.assert(pretty.contains('"Amount" : 12.34'));
    System.assert(pretty.contains('"Tags" : [ "spruce", "lake" ]'));
    DTO decoded = (DTO) JSON.deserialize(compact, DTO.class);
    System.assertEquals('Cabin', decoded.Name);
    System.assertEquals(3, decoded.Count);
    System.assertEquals(12.34, decoded.Amount);
    System.assertEquals('lake', decoded.Tags[1]);
    DTO strictDecoded = (DTO) JSON.deserializeStrict('{"Name":"Strict","Count":4,"Amount":7.50,"Tags":["tight","fit"]}', DTO.class);
    System.assertEquals('Strict', strictDecoded.Name);
    System.assertEquals(4, strictDecoded.Count);
    System.assertEquals(7.50, strictDecoded.Amount);
    System.assertEquals('fit', strictDecoded.Tags[1]);
    Boolean strictRejected = false;
    try {
      JSON.deserializeStrict('{"Name":"Overfull","Count":1,"Extra":"no"}', DTO.class);
    } catch (JSONException e) {
      strictRejected = e.getMessage().toLowerCase().contains('unknown');
    }
    System.assert(strictRejected);
    Map<String, Object> root = (Map<String, Object>) JSON.deserializeUntyped('{"nested":{"label":"bank","values":["spruce","stone"],"meta":{"depth":2}}}');
    Map<String, Object> nested = (Map<String, Object>) root.get('nested');
    List<Object> values = (List<Object>) nested.get('values');
    Map<String, Object> meta = (Map<String, Object>) nested.get('meta');
    System.assertEquals('bank', nested.get('label'));
    System.assertEquals('stone', values.get(1));
    System.assertEquals(2, meta.get('depth'));
  }
}
